-- q2 composicion de la celda contra la po producto ticket concentracion y seasoning
WITH c AS (SELECT CAST(codmes AS VARCHAR) AS cm, tip_doc, key_value, CASE WHEN entidad = 'IBK' THEN '1_IBK' ELSE '2_SSFF' END AS grupo, CASE WHEN flg_clean = 1 THEN '1_clean' ELSE '2_dirty' END AS bucket, CAST(target_12m AS DOUBLE) AS tgt, pd_raw AS pd FROM disc_model_owner.ds_adm_bpe_bankbn_cal WHERE flg_calib = 1 AND flg_clean IN (0, 1)), p AS (SELECT CAST(codmes AS VARCHAR) AS cm, tip_doc, key_value, COALESCE(CAST(tipo_credito AS VARCHAR), 'NA') AS tc, COALESCE(CAST(altas AS VARCHAR), 'NA') AS alt, COALESCE(CAST(flg_garantia AS VARCHAR), 'NA') AS gar, CAST(saldo_m0_ent AS DOUBLE) AS tkt_ent, CAST(saldo_m0 AS DOUBLE) AS sys_m0 FROM disc_model_owner.ds_adm_bpe_bankbn_po), j AS (SELECT c.grupo, c.bucket, c.tgt, c.pd, COALESCE(p.tc, 'SIN_PO') AS tc, p.tkt_ent, CASE WHEN p.sys_m0 > 0 THEN p.tkt_ent / p.sys_m0 END AS share_ent, CASE WHEN p.sys_m0 IS NULL THEN 'x_sin_po' WHEN p.sys_m0 <= 0 THEN 'x_sin_saldo' WHEN p.tkt_ent / p.sys_m0 < 0.25 THEN 'a_share_lt25' WHEN p.tkt_ent / p.sys_m0 < 0.75 THEN 'b_share_25a75' ELSE 'c_share_ge75' END AS banda, CASE WHEN p.alt IN ('A-02','A-03','A-04','A-05') THEN 'r_alta_2a5m' WHEN p.alt IN ('A-06','A-07','A-08','A-09','A-10','A-11') THEN 'm_alta_6a11m' WHEN p.alt = 'A-12' THEN 'n_alta_12m' ELSE 'x_alta_otro' END AS tramo, CASE WHEN p.gar = '01.1 Garantia Preferida' THEN 1e0 ELSE 0e0 END AS garp FROM c LEFT JOIN p ON c.cm = p.cm AND c.tip_doc = p.tip_doc AND c.key_value = p.key_value) SELECT grupo, bucket, COALESCE(banda, tramo, 'TODOS') AS estrato, count(1) AS n, CAST(sum(tgt) AS BIGINT) AS malos, round(100e0 * avg(tgt), 2) AS badrate_pct, round(100e0 * avg(pd), 2) AS pd_media_pct, round(approx_percentile(tkt_ent, 0.5), 0) AS tkt_ent_p50, round(approx_percentile(tkt_ent, 0.9), 0) AS tkt_ent_p90, round(approx_percentile(share_ent, 0.5), 3) AS share_ent_p50, round(100e0 * avg(CASE WHEN tc = '08' THEN 1e0 ELSE 0e0 END), 1) AS pct_tc08, round(100e0 * avg(CASE WHEN tc = '09' THEN 1e0 ELSE 0e0 END), 1) AS pct_tc09, round(100e0 * avg(CASE WHEN tc = '10' THEN 1e0 ELSE 0e0 END), 1) AS pct_tc10, round(100e0 * avg(garp), 1) AS pct_gar_pref, round(100e0 * avg(CASE WHEN tc = 'SIN_PO' THEN 1e0 ELSE 0e0 END), 1) AS pct_sin_po FROM j GROUP BY GROUPING SETS ((grupo, bucket), (grupo, bucket, banda), (grupo, bucket, tramo)) HAVING count(1) >= 50 ORDER BY grupo, bucket, estrato
